#include <bits/stdc++.h>
using namespace std;

const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;
const int INF = 0x3f3f3f3f;

char a[MAXN][MAXN], b[MAXN][MAXN];
int infect[MAXN][MAXN];
int n, T;
const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, 1, 0, -1};

inline bool isDigit0(char c) { return c >= '0' && c <= '9'; }
inline bool isDigit1(char c) { return c >= '1' && c <= '9'; }

class Dinic {
public:
    vector<int> adj[MAXV];
    int cap[MAXV][MAXV];
    int dist[MAXV];
    bool used[MAXV];

    Dinic() { memset(cap, 0, sizeof(cap)); }

    void addEdge(int u, int v, int c) {
        adj[u].push_back(v);
        adj[v].push_back(u);
        cap[u][v] = c;
        cap[v][u] = 0;
    }

    bool bfs(int s, int t) {
        memset(dist, -1, sizeof(dist));
        queue<int> q;
        q.push(s);
        dist[s] = 0;
        while (!q.empty() && dist[t] == -1) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (cap[u][v] > 0 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return dist[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        used[u] = true;
        for (int v : adj[u]) {
            if (cap[u][v] > 0 && !used[v] && dist[v] == dist[u] + 1) {
                int got = dfs(v, t, min(flow, cap[u][v]));
                if (got > 0) {
                    cap[u][v] -= got;
                    cap[v][u] += got;
                    return got;
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int ret = 0;
        while (bfs(s, t)) {
            memset(used, 0, sizeof(used));
            int got;
            while ((got = dfs(s, t, INF)) > 0) ret += got;
        }
        return ret;
    }
};

Dinic dinic;

void zombieBFS(int sx, int sy) {
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            infect[i][j] = INF;
    infect[sx][sy] = 0;
    queue<pair<int,int>> q;
    q.push(make_pair(sx, sy));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (isDigit0(a[nx][ny]) && infect[nx][ny] == INF) {
                infect[nx][ny] = infect[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

void addSourceEdges(int sx, int sy) {
    int dist[MAXN][MAXN];
    memset(dist, INF, sizeof(dist));
    dist[sx][sy] = 0;

    if (isDigit1(b[sx][sy]))
        dinic.addEdge(n * sx + sy, n * n + n * sx + sy, INF);

    queue<pair<int,int>> q;
    q.push(make_pair(sx, sy));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (dist[nx][ny] != INF) continue;
            if (!isDigit0(a[nx][ny])) continue;

            int cur = dist[x][y] + 1;
            if (cur <= min(infect[nx][ny] - 1, T)) {
                dist[nx][ny] = cur;
                q.push(make_pair(nx, ny));
            }
            if (cur <= min(infect[nx][ny], T) && isDigit1(b[nx][ny]))
                dinic.addEdge(n * sx + sy, n * n + n * nx + ny, INF);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    int zx = 0, zy = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            if (a[i][j] == 'Z') {
                zx = i; zy = j;
            } else if (isDigit1(a[i][j])) {
                dinic.addEdge(MAXV - 2, i * n + j, a[i][j] - '0');
            }
        }
    }

    zombieBFS(zx, zy);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> b[i][j];
            if (isDigit1(b[i][j]))
                dinic.addEdge(n * n + i * n + j, MAXV - 1, b[i][j] - '0');
        }
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isDigit1(a[i][j])) addSourceEdges(i, j);

    cout << dinic.maxFlow(MAXV - 2, MAXV - 1) << '\n';
    return 0;
}
